/* @lc app=leetcode id=3261 lang=kotlin */ class Solution { fun countKConstraintSubstrings(s: String, k: Int, queries: Array<IntArray>): LongArray = s.length.let { n -> IntArray(n).let { rt -> (0 until n).fold(Triple(0, 0, 0)) { (r, z, o), l -> generateSequence(Triple(r, z, o)) { (rr, zz, oo) -> if (rr < n && (zz + (if (s[rr] == '0') 1 else 0) <= k || oo + (if (s[rr] == '1') 1 else 0) <= k)) Triple(rr + 1, zz + (if (s[rr] == '0') 1 else 0), oo + (if (s[rr] == '1') 1 else 0)) else null }.last().let { (r2, z2, o2) -> Triple(r2, z2 - (if (s[l] == '0') 1 else 0), o2 - (if (s[l] == '1') 1 else 0)).also { rt[l] = r2 - 1 } } }.let { rt.indices.runningFold(0L) { a, l -> a + rt[l] - l + 1 }.let { pre -> queries.map { (ql, qr) -> generateSequence(ql to qr) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (rt[m] >= qr) lo to m else m + 1 to hi } }.last().first.let { p -> pre[p] - pre[ql] + (qr - p + 1L) * (qr - p + 2L) / 2 } }.toLongArray() } } } } }